    "text": "{\n  \"version\": 1,\n  \"id\": \"bicycle-aggregation\",\n  \"title\": \"Bicycle and its parts\",\n  \"elements\": {\n    \"bicycle\": {\n      \"kind\": \"class\",\n      \"name\": \"Cykel\",\n      \"members\": [\"+ wheels: Hjul[]\", \"+ saddle: Sadel\", \"+ handlebar: Styre\"],\n      \"notes\": \"The whole. Its parts can be removed and reused independently.\",\n      \"display\": {\n        \"collapsed\": { \"name\": \"Cykel\", \"show\": [\"name\", \"kind\", \"count\"] },\n        \"expanded\": { \"name\": \"Cykel — delar\", \"show\": [\"name\", \"members\", \"notes\"] }\n      }\n    },\n    \"wheel\": { \"kind\": \"class\", \"name\": \"Hjul\", \"members\": [\"+ diameter: number\", \"+ Rotate()\"] },\n    \"saddle\": { \"kind\": \"class\", \"name\": \"Sadel\", \"members\": [\"+ material: string\", \"+ AdjustHeight()\"] },\n    \"handlebar\": { \"kind\": \"class\", \"name\": \"Styre\", \"members\": [\"+ width: number\", \"+ Steer(direction)\"] }\n  },\n  \"relationships\": [\n    {\n      \"id\": \"bicycle-has-wheels\",\n      \"kind\": \"aggregation\",\n      \"from\": \"bicycle\",\n      \"to\": \"wheel\",\n      \"toMultiplicity\": \"2\"\n    },\n    {\n      \"id\": \"bicycle-has-saddle\",\n      \"kind\": \"aggregation\",\n      \"from\": \"bicycle\",\n      \"to\": \"saddle\"\n    },\n    {\n      \"id\": \"bicycle-has-handlebar\",\n      \"kind\": \"aggregation\",\n      \"from\": \"bicycle\",\n      \"to\": \"handlebar\"\n    }\n  ],\n  \"views\": [\n    {\n      \"id\": \"bicycle-parts\",\n      \"type\": \"aggregation\",\n      \"title\": \"Bicycle aggregation\",\n      \"elements\": [\"bicycle\", \"wheel\", \"saddle\", \"handlebar\"]\n    }\n  ]\n}\n"
