    "text": "{\n  \"version\": 1,\n  \"id\": \"components\",\n  \"title\": \"A small online shop\",\n  \"elements\": {\n    \"web\": { \"kind\": \"component\", \"name\": \"Web storefront\", \"members\": [\"Product pages\", \"Shopping cart\"] },\n    \"api\": { \"kind\": \"component\", \"name\": \"Shop API\", \"members\": [\"Orders\", \"Checkout\"] },\n    \"catalog\": { \"kind\": \"component\", \"name\": \"Product catalogue\", \"members\": [\"Search\", \"Availability\"] },\n    \"payment\": { \"kind\": \"component\", \"name\": \"Payment provider\", \"members\": [\"Payment authorization\"] }\n  },\n  \"groups\": [\n    { \"id\": \"shop\", \"name\": \"Shop application\", \"members\": [\"web\", \"api\"] },\n    {\n      \"id\": \"services\",\n      \"name\": \"Supporting services\",\n      \"members\": [\"catalog\", \"payment\"],\n      \"display\": {\n        \"initial\": \"collapsed\",\n        \"collapsed\": { \"name\": \"Supporting services\", \"show\": [\"name\", \"count\"] },\n        \"expanded\": { \"name\": \"Service dependencies\", \"show\": [\"name\", \"members\"] }\n      }\n    }\n  ],\n  \"relationships\": [\n    { \"id\": \"web-api\", \"kind\": \"dependency\", \"from\": \"web\", \"to\": \"api\", \"label\": \"orders & products\" },\n    { \"id\": \"api-catalog\", \"kind\": \"dependency\", \"from\": \"api\", \"to\": \"catalog\", \"label\": \"searches products\" },\n    { \"id\": \"api-payment\", \"kind\": \"dependency\", \"from\": \"api\", \"to\": \"payment\", \"label\": \"authorizes payment\" }\n  ],\n  \"views\": [\n    { \"id\": \"shop-components\", \"type\": \"component\", \"title\": \"Shop components\", \"elements\": [\"web\", \"api\", \"catalog\", \"payment\"] }\n  ]\n}\n"
