    "text": "{\n  \"version\": 1,\n  \"id\": \"garage-structure\",\n  \"title\": \"Garage structure\",\n  \"elements\": {\n    \"service\": {\n      \"kind\": \"class\",\n      \"name\": \"GarageService\",\n      \"members\": [\"+ Park(vehicle, garage)\", \"+ CreateGarage(name, capacity)\"],\n      \"notes\": \"Coordinates operations across the garages.\",\n      \"display\": {\n        \"initial\": \"collapsed\",\n        \"collapsed\": { \"name\": \"Garage service\", \"show\": [\"name\", \"count\"] },\n        \"expanded\": { \"name\": \"GarageService · operations\", \"show\": [\"name\", \"kind\", \"members\", \"notes\"] }\n      }\n    },\n    \"garage\": { \"kind\": \"class\", \"name\": \"Garage\", \"members\": [\"+ Capacity: int\", \"+ Park(vehicle)\", \"+ Remove(registration)\"] },\n    \"spot\": { \"kind\": \"class\", \"name\": \"ParkingSpot\", \"members\": [\"+ Number: int\", \"+ Vehicle: Vehicle?\", \"+ Park(vehicle)\", \"+ Clear()\"] }\n  },\n  \"groups\": [\n    {\n      \"id\": \"domain\",\n      \"name\": \"Garage domain\",\n      \"members\": [\"service\", \"garage\", \"spot\"],\n      \"display\": {\n        \"initial\": \"expanded\",\n        \"collapsed\": { \"name\": \"Domain overview\", \"show\": [\"name\", \"count\"] },\n        \"expanded\": { \"name\": \"Garage domain\", \"show\": [\"name\", \"members\"] }\n      }\n    }\n  ],\n  \"relationships\": [\n    {\n      \"id\": \"service-uses-garage\",\n      \"kind\": \"dependency\",\n      \"from\": \"service\",\n      \"to\": \"garage\",\n      \"label\": \"parks vehicles\"\n    },\n    {\n      \"id\": \"garage-uses-spot\",\n      \"kind\": \"dependency\",\n      \"from\": \"garage\",\n      \"to\": \"spot\",\n      \"label\": \"assigns parking\"\n    }\n  ],\n  \"views\": [\n    {\n      \"id\": \"garage-classes\",\n      \"type\": \"class\",\n      \"title\": \"Garage classes\",\n      \"elements\": [\"service\", \"garage\", \"spot\"]\n    }\n  ]\n}\n"
